import { randomUUID } from "node:crypto";
export default function ({ events, allowedSenders, previous }) {
  const allow = String(allowedSenders || "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
  const list = (Array.isArray(events) ? events : []).filter(
    (e) =>
      e?.messageId &&
      (!allow.length ||
        allow.some((a) =>
          String(e.sender || "")
            .toLowerCase()
            .includes(a),
        )),
  );
  const i = previous?.i ?? 0;
  const e = list[i];
  if (!e) return { state: { i }, more: false, messageId: ".", id: "" };
  return { state: { i: i + 1 }, more: true, messageId: e.messageId, id: randomUUID() };
}

