export default function format({ text, id, feedbackUrl }) {
  if (!/^https:\/\//i.test(feedbackUrl) || feedbackUrl.includes("YOUR_"))
    throw Error("Configure feedback URL");
  const escape = (x) =>
    String(x).replace(
      /[&<>"']/g,
      (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
    );
  const link = (vote) => {
    const u = new URL(feedbackUrl);
    u.searchParams.set("id", id);
    u.searchParams.set("feedback", vote);
    return escape(u.href);
  };
  return {
    body:
      "<p>" +
      escape(text).replace(/\n/g, "<br>") +
      '</p><p>Was this message helpful? <a href="' +
      link("Yes") +
      '">Yes</a> · <a href="' +
      link("No") +
      '">No</a></p>',
  };
}

