export default function find({ values, id, feedback, title }) {
  if (!id || !["Yes", "No"].includes(feedback)) throw Error("Invalid feedback");
  const rows = values.map((r, i) => (r[0] === id ? i : -1)).filter((i) => i >= 0);
  if (rows.length !== 1) throw Error("Feedback ID was not found uniquely");
  return { range: "'" + title.replace(/'/g, "''") + "'!D" + (rows[0] + 1), values: [[feedback]] };
}

